// `on key_down(Key.Space)` runs when the key goes down; handlers may assign scene state.
scene Demo {
    state speed: f32 = 0.7;

    camera Main {
        position: vec3(0.0, 2.0, 5.0);
        target: vec3(0.0, 0.5, 0.0);
    }

    entity Cube {
        mesh: Box {};

        update(dt: f32) {
            self.rotation *= quat.axis_angle(vec3(0.0, 1.0, 0.0), speed * dt);
        }
    }

    on key_down(Key.Space) {
        speed = -speed;
    }
}

// `update(dt)` runs every frame; assign to `self.rotation` to turn the entity.
scene Demo {
    state speed: f32 = 0.7;

    camera Main {
        position: vec3(0.0, 2.0, 5.0);
        target: vec3(0.0, 0.5, 0.0);
    }

    entity Cube {
        mesh: Box {};
        position: vec3(0.0, 0.5, 0.0);

        update(dt: f32) {
            self.rotation *= quat.axis_angle(vec3(0.0, 1.0, 0.0), speed * dt);
        }
    }
}

// `spawn(Prefab { params })` creates an entity from a handler or update; `destroy(self)` removes one.
prefab Crate {
    param origin: vec3 = vec3(0.0, 4.0, 0.0);

    position: origin;
    mesh: Box {};
    body: Dynamic { mass: 1.0; };
    collider: BoxCollider { size: vec3(1.0, 1.0, 1.0); };

    fixed_update(dt: f32) {
        if self.position.y < -10.0 {
            destroy(self);
        }
    }
}

scene Demo {
    camera Main {
        position: vec3(0.0, 4.0, 12.0);
        target: vec3(0.0, 1.0, 0.0);
    }

    entity Floor {
        position: vec3(0.0, -0.5, 0.0);
        mesh: Box { size: vec3(10.0, 1.0, 10.0); };
        body: Static {};
        collider: BoxCollider { size: vec3(10.0, 1.0, 10.0); };
    }

    on key_down(Key.C) {
        spawn(Crate { origin: vec3(0.0, 6.0, 0.0); });
    }
}

// A material's `fragment` runs per pixel on the GPU; the `fn` helpers it calls must be GPU-safe.
fn pulse(t: f32) -> f32 {
    return 0.65 + 0.35 * sin(t);
}

material Pulse {
    param tint: color = #6b5cff;
    param phase: f32 = 0.0;

    fragment(input: SurfaceInput) -> color {
        return color.linear(tint.rgb * pulse(phase), tint.a);
    }
}

scene Demo {
    camera Main {
        position: vec3(0.0, 2.0, 5.0);
        target: vec3(0.0, 0.5, 0.0);
    }

    entity Cube {
        mesh: Box {};
        material: Pulse { phase: bind(frame.time); };
    }
}
